def dep_a():
    return Security(oauth2_scheme, scopes=["scope1"])

def dep_b():
    return Security(oauth2_scheme)

@app.get("/test1")
def test1(a=Depends(dep_a), b=Depends(dep_b)):
    return {"message": "test1"}

@app.get("/test2")
